ROOT=Path.cwd().resolve();OWN=Path(__file__).resolve().parent;REL=OWN.relative_to(ROOT);BASE=OWN.parent;AUTH=BASE/'chemie-q1-six-source-operator-remediation-current-candidate-v1';AREL=AUTH.relative_to(ROOT)
ISO=ROOT/'tmp/chemie-q1-seven-reviewed-integration-candidate-v3-native-root';OUT=ISO/AREL/'native-finalbook-v2';HOLD='d3cd250f-5221-589d-aa1c-44a4692d1acb'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def read(p):return json.loads(Path(p).read_text())
def write(p,v):
 p=Path(p);p.parent.mkdir(parents=True,exist_ok=True);assert not p.is_symlink();p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
