pair={};copied=[]
for letter,directory in [('a','chemie-q1-seven-source-operator-current-independent-d-a-v1'),('b','chemie-q1-eight-current-independent-d-b-v1')]:
 dest=OUT/('round-'+letter)/'results';dest.mkdir(exist_ok=True);assert not list(dest.iterdir())
 for src in sorted((BASE/directory/'results').iterdir()):
  assert src.name.endswith(('.records.jsonl','.run.json'));shutil.copy2(src,dest/src.name);copied.append({'sourcePath':str(src.relative_to(ROOT)),'isolatePath':str((dest/src.name).relative_to(ISO)),'sha256':sha(src)})
 pair[letter]={r['goalId']:r for f in dest.glob('*.records.jsonl') for r in map(json.loads,f.read_text().splitlines())}
ids=read(AUTH/'batch.config.json')['goalIds'];assert list(pair['a'])==ids and list(pair['b'])==ids
for gid in ids:
 a,b=pair['a'][gid],pair['b'][gid]
 for k in ['goalId','goalFingerprint','pageFingerprint','bookDigest','bundleFingerprint','currentTitleDe','currentTitleEn','currentDescriptionDe','currentDescriptionEn']:assert a[k]==b[k],(gid,k)
 if gid!=HOLD:assert a['decision']==b['decision']=='keep'
assert pair['a'][HOLD]['decision']=='keep' and pair['b'][HOLD]['decision']=='split_review'
reasons={
'70b34ae7':('Beide tatsächlichen Runden prüfen die neue direkte Nachfolgerbindung an die eigenständige HE-LK-Parabenverwendung. Das ganze bestehende Zielobjekt, Bild und seine externe gültige P-/A-/M-/V-Evidenz bleiben unverändert; create aus einem Null-Buchprofil ist keine Aufhebung dieser externen Evidenz. Nur die aktuelle Seiten-/Kontextbindung wird wiederhergestellt, kein neuer Fachabschluss.','Both actual rounds check the new direct successor binding to the distinct HE advanced-level paraben-use goal. The entire existing goal object, image and valid external P/A/M/V evidence remain unchanged; create from a null book field does not revoke external evidence. Restore only the current page/context binding, without a new scientific completion.'),
'057a6826':('Die vollständigen Runden erhalten einen einzigen begründeten Acylreaktivitätsvergleich unter vergleichbaren Bedingungen; Carbonylgruppe und Abgangsgruppe begründen dieselbe Rangfolge. RP-Vertiefungsbeispiele liefern Kontext, keine allgemeine normative Pflichtzeile. Der fehlende direkte Atlas-Eintrag und das ehrliche eigene LK-Transferziel bleiben sichtbar. Das bestehende fachlich richtige JPG bleibt exakt.','The full rounds retain one justified acyl-reactivity comparison under comparable conditions; the carbonyl group and leaving group explain the same ranking. RP extension examples provide context, not a universal normative clause. Preserve the missing direct atlas row and truthful authored advanced-level transfer scope. Keep the scientifically correct existing JPG exactly.'),
'39c85aa0':('Beide tatsächlichen Runden verbinden intramolekulare Esterbildung mit ringbezogenen Vergleichsdaten. Ringgliederbilanz und Wasserbildung stimmen; Bildungstendenz ist weder universelle Fünf-/Sechsringregel noch mit Geschwindigkeit gleichgesetzte Stabilität. Das eigene LK-Transferziel erhält HE-Ester-/Hydroxykontext ohne behauptete vollständige normative Atlas-Zeile und sein unverändertes gutes JPG.','Both actual rounds connect intramolecular esterification with ring-related comparison data. Ring-member accounting and water formation are correct; formation tendency is neither a universal five/six-membered ring rule nor stability equated with rate. The authored advanced-level transfer retains HE ester/hydroxy context without a claimed complete normative atlas row, and its unchanged good JPG.'),
'd742ecb0':('Planen UND tatsächliches Durchführen bleiben in beiden Sprachen und beiden unabhängigen Runden erforderlich. CMC, begrenztes Schaumvolumen und Schmutztragevermögen dienen einem kontrollierten Leistungsvergleich; Fremddaten ersetzen keine Durchführung. BB-Grenzflächenkontext ist Teil-/Transferbeleg, kein erfundener vollständiger HE-LK-CMC-Operator. Die aktuelle getrennte schematische PNG-Darstellung ist passend.','Planning AND actual execution remain required in both languages and both independent rounds. CMC, bounded foam volume and dirt carrying support one controlled performance comparison; supplied data do not substitute for execution. BB interfacial context is partial/transfer evidence, not an invented complete HE advanced-level CMC operator. The current distinct schematic PNG representations are appropriate.'),
'd76b80a2':('Beide Runden erhalten materialgestützte Wirkweise UND begründete Dosierungsbeurteilung. HE-GK/LK-Sorbinsäure bleibt von HE-LK-Paraben getrennt; die konkrete datierte Kategorie, Summen-/Säurebasis und Fußnoten werden geprüft. Die Mousse-Anwendung ist ein begrenzter Unterrichtsfall zum gegebenen Stand, keine aktuelle Produkt-, Sicherheits- oder Rechtsfreigabe; ganze NW-Quellen bleiben nur partial.','Both rounds retain material-supported action AND justified dosage assessment. HE general/advanced sorbic acid remains separate from advanced paraben use; check the specified dated category, sum/acid basis and footnotes. The mousse application is a bounded classroom case at the supplied date, not present-day product, safety or legal clearance; whole NW sources remain partial.'),
'10f657bc':('Beide vollständigen Runden bestätigen Ascorbinsäure als Elektronendonator und das getroffene Redoxurteil auf bereitgestellten Vergleichsdaten. Antioxidative Wirkung belegt keine antimikrobielle Konservierung. Eigener LK-Transfer und fehlende direkte normative Atlas-Zeile bleiben ehrlich; das tatsächliche historische PNG bleibt exakt, keine Lernendenbeobachtung wird behauptet.','Both full rounds confirm ascorbic acid as the electron donor and a redox judgement grounded in supplied comparison data. Antioxidant action does not establish antimicrobial preservation. Preserve the truthful authored advanced-level transfer and missing direct normative atlas row; retain the exact actual historical PNG and claim no learner observation.'),
'0d59b62e':('Beide Runden bestätigen genau den tatsächlichen HE-Q1.5-B05-Verwendungsoperator ausschließlich LK. Para-Hydroxybenzoesäureesterstruktur, Löslichkeit, Wirkungsdaten und datierte produktbezogene Bedingungen dienen einem materialgebundenen Verwendungsentscheid mit Ester-/Sorbinsäurevoraussetzungen. Die quantitative Ascorbin-/Parabendetermination bleibt getrennt offen; keine Rechts-/Produktfreigabe und keine GK-Ausdehnung.','Both rounds confirm the actual HE Q1.5 B05 use operator exclusively at advanced level. The para-hydroxybenzoic ester structure, solubility, efficacy data and dated product conditions support one material-bound use decision with ester/sorbic prerequisites. The quantitative ascorbic/paraben determinations remain separately open; no legal/product clearance or expansion to general level.')}
author={'schemaVersion':1,'manifestId':'chemie-q1-six-safe-plus-context-reviewed-synthesis-20261005-v3','synthesizedBy':'Codex independent technical integration after complete frozen A and B records and separate P and V reviews','decisions':[{'goalId':g,'resolutionDecision':'keep_current' if g.startswith('70b34') else 'current_after_revision','evidenceRound':'second','rationaleDe':reasons[g[:8]][0],'rationaleEn':reasons[g[:8]][1]} for g in ids if g!=HOLD],'deferredGoals':[{'goalId':HOLD,'rationaleDe':'Offener semantischer Splitbefund: Zwei unabhängig gelingende oder scheiternde quantitative Bestimmungen sind im tatsächlichen Text nicht durch eine gemeinsame vergleichende Fragestellung integriert. Die frühere atomic-Begründung darf nicht operativ übernommen werden. Beide beanspruchten Analyten und tatsächliche Durchführung bleiben erhalten; eine echte atomare Aufteilung mit eigenen aktuellen unabhängigen Nachweisen ist erforderlich. Kein Beschreibungs-/A-Abschluss dieses alten Aggregatkandidaten.','rationaleEn':'Open semantic split finding: the actual text does not integrate two independently successful or unsuccessful quantitative determinations through a shared comparative question. Do not operationally adopt the earlier atomic rationale. Retain both claimed analytes and actual execution; require a genuine atomic split with independent current evidence. No description or atomicity completion for this old aggregate candidate.'}]}
write(OUT/'synthesis-authoring.json',author);write(OWN/'complete-pair-science-and-explicit-deferral.actual.json',{'atUTC':datetime.now(timezone.utc).isoformat(),'actualIndependentPairFiles':copied,'allEightBindingFieldsExact':True,'specificBilingualSafeSynthesis':author,'safeNewScientificCandidateCount':6,'existingContextRestorationCount':1,'openSplitCandidateCount':1,'PRecommendationsResolvedAgainstActualSeparateFrozenP':'7 independent P profiles exist externally with native check pass; book field null is truthful and human review remains pending. Deferred d3cd P is not adopted.','newHumanApproval':False,'activeWrites':0})
terminal=[]
def run(name,args):
 p=subprocess.run(args,cwd=ISO,capture_output=True);o=OWN/(name+'.stdout.txt');e=OWN/(name+'.stderr.txt');o.write_bytes(p.stdout);e.write_bytes(p.stderr);terminal.append({'name':name,'command':args,'cwd':str(ISO),'actualExitCode':p.returncode,'stdoutPath':str(o.relative_to(ROOT)),'stdoutSHA256':sha(o),'stderrPath':str(e.relative_to(ROOT)),'stderrSHA256':sha(e)});write(OWN/'native-safe-synthesis-finalization.actual.receipt.json',{'commands':terminal,'activeWrites':0,'newHumanApproval':False});print(json.dumps({'name':name,'exit':p.returncode,'stdout':p.stdout.decode()[:900],'stderr':p.stderr.decode()[:1700]}),flush=True);assert p.returncode==0
cfg=str(AREL/'batch.config.json');out=str(AREL/'native-finalbook-v2')
run('safe-dual-summarize',['app/node_modules/.bin/tsx','app/scripts/materializeGoalDescriptionRolloutBatch.ts','summarize','--config',cfg,'--write'])
run('safe-synthesis-manifest',['app/node_modules/.bin/tsx','app/scripts/materializeGoalDescriptionRolloutSynthesisManifest.ts','--config',cfg,'--authoring',out+'/synthesis-authoring.json','--write'])
run('safe-seven-resolutions',['app/node_modules/.bin/tsx','app/scripts/materializeGoalDescriptionRolloutResolutions.ts','--config',cfg,'--synthesis-manifest',out+'/synthesis-decisions.json','--write'])
run('safe-seven-final-index',['app/node_modules/.bin/tsx','app/scripts/materializeGoalDescriptionRolloutBatch.ts','finalize','--config',cfg,'--write'])
run('safe-seven-final-index-check',['app/node_modules/.bin/tsx','app/scripts/materializeGoalDescriptionRolloutBatch.ts','finalize','--config',cfg])
shutil.copytree(OUT,OWN/'native-finalbook');idx=read(OWN/'native-finalbook/resolution-index.json');assert len(idx['resolutions'])==7 and idx['deferredGoalIds']==[HOLD] and all(r['strictDescriptionComplete'] for r in idx['resolutions'])
write(OWN/'native-safe-finalized-tree.actual.receipt.json',{'nativeFinalIndexSHA256':sha(OWN/'native-finalbook/resolution-index.json'),'actualResolvedDescriptions':7,'newScientificClosureCandidates':6,'existingContextRestorationCandidates':1,'explicitDeferredGoalIds':[HOLD],'nativeAuthorBundleBookAndPagesUnchanged':True,'sourcePhysicalDirectory':str(OUT),'isolationRoot':str(ISO),'activeScientificClosures':0,'activeStrictNetIncrease':0,'activeWrites':0,'humanApproval':False})
print(json.dumps({'nativeDescriptionResolved':7,'deferredGoalIds':[HOLD],'activeClosures':0,'root':str(ISO)}))
